import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"DeepLx 项目","description":"","frontmatter":{"plugin":"windingwind/zotero-pdf-translate"},"headers":[],"relativePath":"user-guide/plugins/translate/deeplx.md","filePath":"wiki/user-guide/plugins/translate/deeplx.md"}`),u=Object.assign({name:`user-guide/plugins/translate/deeplx.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginstranslatedeeplx.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`deeplx-项目`,tabindex:`-1`},[o(`DeepLx 项目 `),i(`a`,{class:`header-anchor`,href:`#deeplx-项目`,"aria-label":`Permalink to “DeepLx 项目”`},`​`)],-1),r(s),u[2]||=a(`<p>由于各种原因，在国内注册 DeepL 的免费计划都十分困难。于是出现了 <a href="https://github.com/OwO-Network/DeepLX/?tab=readme-ov-file" target="_blank" rel="noreferrer">DeepLX</a> 项目，该项目可让用户在不注册账号的前提下，使用 DeepL 作为翻译服务。</p><p>DeepLX 是一款基于 DeepL 翻译引擎的开源工具，旨在为用户提供免费、高质量的翻译服务。它通过调用 DeepL 的 API 接口，实现文本、文档等多种内容的翻译功能。DeepLX 的优势在于其翻译质量高，支持多种语言，且操作简单易用。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>DeepLX 的使用需要进行部署，涉及 Docker 或服务器相关知识。如果您对此不太熟悉，建议选择其他翻译引擎。</p></div><p>主要特点：</p><ul><li><p>高质量翻译：基于 DeepL 引擎，翻译结果准确、自然。</p></li><li><p>多语言支持：支持包括英语、中文、日语、法语、德语等在内的多种语言互译。</p></li><li><p>免费使用：相较于 DeepL 官方服务的收费模式，DeepLX 提供免费翻译服务。</p></li><li><p>开源项目：代码公开，用户可自行部署或修改，满足个性化需求。</p></li><li><p>跨平台支持：可在 Windows、macOS、Linux 等系统上运行。</p></li></ul><p>使用教程见：<a href="https://deeplx.owo.network/" target="_blank" rel="noreferrer">DeepLX</a></p><p>一些衍生项目：</p><ul><li><p>本地部署 DeepLX：<a href="https://github.com/ycvk/deeplx-local" target="_blank" rel="noreferrer">deeplx-local</a></p></li><li><p>使用 FreeBSD (Serv00) 环境中使用部署<a href="https://github.com/aigem/deeplx-freeAPI-serv00" target="_blank" rel="noreferrer">deeplx-freeAPI-serv00Public</a>，<a href="https://www.bilibili.com/video/BV1e9bceoECw/" target="_blank" rel="noreferrer">点击查看视频教程</a></p></li></ul><details class="details custom-block"><summary>如何申请免费的 Serv00</summary><p>访问 <a href="https://www.serv00.com/" target="_blank" rel="noreferrer">Serv00 官网</a>，注意看是否有名额注册，点击「注册账户」进入注册页面。</p><p><img src="/assets/deepl-serv00.DeugJQdD.png" alt="Serv00" width="757" height="635"></p><p>1.输入用户名、邮箱、验证码等信息，托管费用填写 0，然后点击「创建账户」。</p><p>2.注意，官方要求至少每隔 3 个月登录一次，否则账号可能被删除。</p><p>3.如果遇到「Maintenance time. Try again later」的提示，是由于 IP 不够纯净的问题。</p><p>通过以上步骤，您可以顺利申请 Serv00 服务。</p></details>`,9),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};